from docx_kit import Doc
import refdata as R
from pathlib import Path
D=Doc('Руководство оператора','ELKA v8.2 • реальная номенклатура ЁЛКА • ремонтный отдел',version='8.2')
D.h1('1. Что устанавливается и где работать')
D.p('Книга оператора принимает документы движения. Просмотрщик получает опубликованный снимок и не меняет учёт. В рабочем шаблоне заполнены номенклатура, спецификации, объединения, ПФД, заказы, места, адреса и операции; журнал пуст. В демо проведены учебные операции. Не переносите демо-остатки в рабочий учёт.')
D.note('Работайте в установленной книге .xlsm. Файлы .xlsx в Setup\\Workbooks — основы для установщика, а не книги с готовыми макросами. Установщик собирает .xlsm в Microsoft Excel на Windows. Не переименовывайте .xlsx в .xlsm вручную.','warn')
D.steps(['Полностью распакуйте архив в папку, например C:\\Temp\\ELKA_v8_2.','Закройте Excel. Для обучения запустите 2_INSTALL_DEMO.cmd. Для рабочего учёта — 1_INSTALL_OPERATOR.cmd.','Укажите папки архива, публикаций и резервных копий. Для общего доступа используйте сетевые пути с правами оператора на запись и пользователей на чтение.','Откройте установленную книгу по ярлыку. Сначала прочитайте инструкцию и проверьте справочники.','Нажмите Проверить книгу, затем выполните учебный ремонт на копии. Только после приёмки переходите к рабочему журналу.'])
D.h1('2. Основные правила ввода')
D.bullets(['Первая строка данных на справочных листах и в журнале — 4; заголовки — строка 3. На Вводе строки документа начинаются со строки 16.','Жёлтые ячейки предназначены для ввода, зелёные — формулы. Остатки вручную не исправляйте.','Один документ содержит одну операцию и одну или несколько позиций; каждой позиции соответствует строка журнала.','Артикулы, номера заказов и коды операций вводите как текст без изменения букв, дефисов и суффиксов исполнений.','Не меняйте маршрут операции, если по ней уже есть движения: история пересчитывается по справочнику операций. Для нового маршрута создавайте новый уникальный код.'])
D.h1('3. Проведение обычного документа — пошагово')
D.steps(['Откройте Ввод. При необходимости нажмите Очистить.','C4: дата операции. C5: выберите операцию из списка или введите код. Откуда (C6) и Куда (C7) определяются автоматически.','C8: номер заказа. Если операция требует заказ, он не может быть пустым. Заведите заказ заранее на листе Заказы.','C9: код изделия/ПФ, если операция требует его. C10: партия/поставка. C11: пояснение.','Начиная со строки 16 заполните код в B и положительное количество в E. Наименование, единица и доступный остаток рассчитываются.','F: адрес откуда, G: адрес куда. Адрес должен принадлежать своему месту. Если количество распределено по нескольким адресам, используйте отдельные строки.','Прикрепите файлы кнопкой вложений; отображаемое название может быть произвольным, расширение и исходное имя менять не требуется.','Проверьте строки и нажмите ПРОВЕСТИ. Убедитесь, что появился номер документа в Движении и изменились Остатки.','Сохраните книгу. Обновите отчёты и опубликуйте данные для пользователей.'])
D.h1('4. Ремонтный отдел: маршрут ПР → РЕМ → ПР')
D.p('РЕМ — отдельное учитываемое место «Ремонтный отдел». Оно не является списанием, браком или сборкой. Перемещается тот же артикул; общий остаток ПР + РЕМ не меняется. В ремонте может оставаться незавершённый остаток. Из РЕМ товары возвращаются только в производство.')
D.table(['Параметр','Передать в ремонт','Вернуть после ремонта'],[
['Операция','45 Передача в ремонт (ПР → РЕМ)','46 Возврат из ремонта (РЕМ → ПР)'],['Заказ C8','Номер существующего заказа','Тот же заказ для прослеживаемости'],['Код B16','Фактический артикул из Справочника','Тот же артикул, что передавали'],['Количество E16','Фактически передано','Фактически возвращено, не больше остатка РЕМ'],['Адрес F16','Фактический участок ПР, например ПР-УЧ1','РЕМ-01 либо другой адрес РЕМ с остатком'],['Адрес G16','РЕМ-01 — принят в ремонт','ПР-УЧ1 или ПР-УЧ2 — куда вернулся'],['Комментарий C11','Причина, дефект, заявка, ответственное лицо','Результат ремонта, ссылка на заявку/передачу'],['Вложения','Акт, фото или документ по необходимости','Акт ремонта и фото по необходимости']],widths=[3,7,7])
D.h2('Пример: передать 10, вернуть 6, затем ещё 4')
D.steps(['Убедитесь, что в ПР есть не меньше 10 выбранного артикула. Если нет: сначала оформите 05 ЦС → ПС, затем 06 ПС → ПР с заказом и изделием.','На Вводе выберите 45, укажите заказ, код, 10, адрес ПР-УЧ1 → РЕМ-01. Проведите. В ПР станет на 10 меньше, в РЕМ на 10 больше.','Выберите 46, тот же заказ и артикул, 6, РЕМ-01 → ПР-УЧ1. Проведите. В РЕМ останется 4.','Когда оставшиеся 4 отремонтированы, проведите 46 на 4. Остаток ремонта по этому артикулу станет нулевым, если других передач не было.','В Движении фильтруйте по коду, заказу и операциям 45/46. В Остатках смотрите РЕМ. В Остатки_адреса смотрите конкретную ячейку.'])
D.note('На РЕМ-02 можно сразу принимать отдельные партии, готовые к возврату. Внутренней операции РЕМ-01 → РЕМ-02 в стандартном наборе нет: для такого сценария администратор должен завести отдельный маршрут РЕМ → РЕМ. Не переименовывайте адрес в уже проведённых строках.','warn')
D.p('Ремонт исключён из списка мест для комплектности по умолчанию: ЦС|ПС|ПР. Поэтому доступность для сборки не завышается ремонтными остатками. Возврат нельзя провести сверх общего остатка РЕМ и остатка выбранного адреса при включённых проверках. Привязка к конкретной передаче и партии не блокирующая: для детального учёта заполняйте заказ, партию и комментарий одинаково.')
D.p('Операция 47 — только входящий остаток РЕМ при переносе начальных данных или свёртке. Для обычного ремонта используйте исключительно 45/46. Автоматическая свёртка ремонта этим обновлением не добавляется.')
D.h1('5. Все операции текущего набора')
D.p('Коды ниже взяты из справочника этой версии. Номер кода важнее примеров из старых версий. «Заказ», «Изделие» — обязательность соответствующих полей; запрос файла допускает осознанное подтверждение проведения без вложения.')
D.table(['Код','Операция','Откуда → куда','Заказ / изделие / файл'],[[o[0],o[1],o[2]+' → '+o[3],o[4]+' / '+o[5]+' / '+o[6]] for o in R.OPS],widths=[1.1,8,3.3,4.6],size=8)
D.h1('6. Как заводить данные на каждом листе')
sections=[
('Справочник','Одна строка на артикул. Заполните уникальный Код, Наименование, Тип, Ед., Группу, при необходимости минимум и адрес по умолчанию, Активно = Да. Вариантное исполнение имеет обычный складской тип (например Деталь), а в Базовом коде указывает семейство с типом Вариантный родитель. Родитель не участвует в движениях; проводите конкретное исполнение.'),
('Спецификация','Одна строка на компонент изделия: код изделия, код компонента, норма на одну единицу. Повторяйте код изделия во всех его строках. Наименования и единицы заполняются формулами. Не задавайте изделие компонентом самого себя. Для допуска любого исполнения используйте вариантного родителя как компонент.'),
('Объединения','У позиции-комплекта в Справочнике тип Объединение. Введите код объединения, компонент, количество на одно объединение. Комплектование списывает составляющие с ЦС и приходует объединение на ЦС; разбор делает обратное. Не используйте эти операции для обычной выдачи в ремонт.'),
('Некомплектные_ПФ','Отдельный код ПФД с типом Некомплектный ПФ; укажите, что собираем, отсутствующий компонент и дефицит на один ПФД. Для нескольких недостающих компонентов повторите код ПФД строками. Норма дефицита не должна превышать норму в спецификации целевого изделия. Изменение дефицита оформляйте отдельным кодом ПФД, чтобы сохранить историю.'),
('Заказы','Уникальный номер, дата, код исполнения изделия, план и примечание. Выпущено, В некомплекте, Отгружено и остаток плана — формулы по журналу. Учебные заказы ЗК-2026-01 и другие замените/дополните реальными до начала работы.'),
('Места хранения','Уникальный код, понятное имя, тип, учитывать ли в остатках. До 12 учитываемых мест в стандартном отчёте; в текущем наборе их 8, включая РЕМ. Номер столбца рассчитывается по порядку учитываемых строк. В Склад в 1С введите точное название из выгрузки; несколько синонимов разделяйте точкой с запятой.'),
('Адреса','Уникальный адрес, код места, зона, стеллаж, полка, ячейка и Активен = Да. Можно оставить детализацию пустой для участка производства. Адрес РЕМ-01 принадлежит только месту РЕМ. Старый адрес с движениями не удаляйте и не перепривязывайте; при выводе из работы сначала обнулите остаток.'),
('Операции','Добавьте свободный код, текст выбора с кодом в начале, существующие места откуда/куда, признаки заказа/изделия/файла, вид документа, Активна = Да и пояснение. Не занимайте служебные коды 01–47 из текущего набора. Число строк можно расширять; выпадающие списки стандартно подготовлены до строки 300 — за этим пределом расширьте их источники либо вводите код вручную.'),
('Настройки','Укажите доступные папки. Запрет отрицательных остатков и Контроль остатков по адресам оставьте Да. Места для комплектности оставьте ЦС|ПС|ПР: не добавляйте РЕМ, пока ремонтные детали нельзя считать готовыми к сборке. Коды автоматических операций меняйте только вместе со справочником маршрутов.'),
('Файлы и Просмотр','Файлы — реестр вложений. Присваивайте удобный заголовок каждому файлу. Для нескольких вложений используйте кнопку повторно. Файлы копируются в архив по настройке, исходное имя хранится отдельно. В Просмотре показываются поддерживаемые фото; PDF/Word/Excel открываются внешней программой. Не меняйте служебные ID и относительные пути вручную.'),
('Импорт_1С и Сравнение_1С','Сначала подготовьте выгрузку с артикулом, складом и количеством, сохраните Excel. Кнопка загрузки считывает файл в Импорт_1С, затем строит сравнение. Сверяйте одинаковую дату, единицы и состав складов. В Местах хранения сопоставьте ремонтный отдел с точным именем склада 1С. Если 1С включает ремонт в Производство, нужна согласованная схема агрегирования — сравнение отдельных мест иначе даст ожидаемые различия.'),
('Остатки, Остатки_адреса, Свод_вариантов, Комплектность','Это отчёты, а не ввод. Остатки работают на формулах. Остальные отчёты обновляются кнопкой Обновить отчёты и перед публикацией. Изменения записывайте только документами движения либо через исправление ошибочного документа.'),
('Контроль','Нажмите Проверить книгу. Ошибки и предупреждения раскрываются со ссылкой на проблемную строку. Исправляйте первичный справочник, адрес, движение или файл и повторяйте проверку. Отсутствие ошибок не заменяет сверку физического количества.'),
('Корзина и Движение_удалённые','Удалённые строки попадают в соответствующий служебный лист. Выделите нужную строку и выберите восстановление. Историческую номенклатуру нельзя физически удалять: используйте Активно = Нет. Нельзя восстанавливать удалённый артикул поверх уже существующего кода.')]
for title,text in sections:
 D.h2(title);D.p(text)
D.h1('7. Сборка, ПФД и варианты')
D.steps(['Выдайте компоненты в ПР операцией 06 с номером заказа и изделием.','На Вводе укажите заказ C8, изделие/ПФ в C9 и количество C13. При необходимости используйте Заполнить по спецификации для просмотра состава.','Нажмите Собрать. Компоненты списываются ПР → СБОРКА, полуфабрикат приходит в ПР, готовое изделие — в ГП, некомплектный ПФ — в ПФД.','Вариантные компоненты подбираются из конкретных активных исполнений по их наличию в ПР. Если нужно строго конкретное исполнение, укажите его в спецификации.','Для ПФД проверьте отсутствующие компоненты на специальном листе. Когда они пришли в ПР, используйте Доукомплектовать. Не оформляйте повторно полный выпуск поверх имеющегося ПФД.'])
D.h1('8. Вставка, удаление и исправление строк')
D.steps(['Перед массовыми изменениями нажмите Резервная копия.','Для вставки выделите ячейку/номер строки в нужном месте и вызовите правой кнопкой ELKA: вставить строки; введите количество. Формулы и оформление должны перенестись.','Заполните новые строки только в полях ввода. В источниках выпадающих списков есть конечные диапазоны: при выходе за них попросите администратора расширить проверку данных. Excel также имеет предел 1 048 576 строк на лист.','Удаление выполняйте через ELKA, а не очисткой всего листа. Журнал переносит удалённые строки в Движение_удалённые.','Для ошибочного многострочного документа выделяйте все его строки по номеру документа, чтобы не оставить неполный документ. Перед восстановлением проверьте последовательность и остатки: восстановление строки само по себе не проверяет будущие расходы.','После изменений нажмите Обновить отчёты, Проверить книгу и сохраните.'])
D.h1('9. Публикация и просмотрщик')
D.p('Нажмите ОПУБЛИКОВАТЬ после проверки. Пользователь нажимает Обновить в просмотрщике и получает Остатки, Остатки_адреса, Движение, Комплектность и реестр вложений. Столбец РЕМ и операции 45/46 переносятся вместе с остальными данными. Просмотрщик показывает время публикации: он не является прямым подключением к открытой книге оператора.')
D.h1('10. Обновление и границы проверок')
D.p('4_UPDATE_MACROS.cmd обновляет установленную книгу структуры v8.1/v8.2 с резервной копией и добавляет РЕМ, адреса и операции 45–47 без повторных строк. При конфликте кода или маршрута обновление остановится. Для старой v6.1 этот сценарий не является миграцией структуры: установите новую книгу и отдельно переносите согласованные остатки/историю. Не запускайте обновление v8.2 прямо на v6.1.')
D.p('Проверки в комплекте выполнены в Linux через LibreOffice с совместимостью VBA и независимой сверкой журнала. Настольный Microsoft Excel, PowerShell, COM-установка, ярлыки, проводник Windows и диалоги открытия файлов требуют окончательной приёмки на рабочем компьютере. Не считайте эти функции проверенными в Windows только по наличию автоматического протокола.')
D.save('/data/v82/docs/out/02_Operator_RU.docx')
# Separate repair quick reference
Q=Doc('Ремонтный отдел — быстрый старт','ELKA v8.2',version='8.2')
Q.h1('Что изменено'); Q.p('Добавлено учитываемое место РЕМ, адреса РЕМ-01/РЕМ-02 и операции 45/46. При передаче в ремонт общий остаток не списывается. В доступный для сборки остаток ремонт не входит.')
Q.h1('Как оформить');Q.steps(['На Вводе выберите 45. Дата C4, заказ C8, артикул B16, количество E16, адрес F16 = участок ПР, G16 = РЕМ-01. При необходимости прикрепите акт и фото. Проведите.','Для возврата выберите 46. Тот же артикул и заказ, фактически возвращаемое количество, F16 = РЕМ-01, G16 = фактический участок ПР. Проведите.','Частичный возврат разрешён. Например передано 10, возвращено 6 — в РЕМ осталось 4.','Обновите отчёты, проверьте РЕМ в Остатках и опубликуйте. Пользователь обновляет просмотрщик.'])
Q.note('Ремонт учитывается по артикулу и адресу. Контроль конкретной заявки, партии и связи возврата с передачей ведите номером заказа и комментарием; отдельного реестра ремонтных заявок нет.','warn')
Q.h1('Установка');Q.p('Полностью распакуйте архив. Для обучения 2_INSTALL_DEMO.cmd; для новой рабочей книги 1_INSTALL_OPERATOR.cmd. Для книги v8.1/v8.2 — 4_UPDATE_MACROS.cmd с резервной копией. .xlsm собирается установщиком в Excel на Windows. Подробности — 01_Install_RU.pdf и 02_Operator_RU.pdf.')
Q.h1('Приёмка в Excel');Q.steps(['Установите демо на отдельной папке. Выполните 45 и 46 на небольшой сумме, включая частичный возврат.','Проверьте отказ возврата сверх остатка, сохранение/закрытие/повторное открытие, просмотр вложений и публикацию.','После успешной проверки работайте в рабочей книге с пустым журналом, не в демо.'])
Q.save('/data/v82/docs/out/05_Repair_Department_RU.docx')
print('docs written')
